function HeroSearch({ brands, brand, setBrand, body, setBody, search, setSearch, maxPrice, setMaxPrice, scrollCatalog, lang }) {
  const formRef = useRef(null);
  useLayoutEffect(() => {
    const form = formRef.current;
    const hero = form?.closest('.hero');
    if (!hero) return;
    let shift = 0;
    // Keep this card at the same right inset without changing the surrounding layout.
    const alignForm = () => {
      if (!form.isConnected) return;
      if (window.matchMedia('(max-width: 900px)').matches) {
        shift = 0;
        form.style.translate = '';
        return;
      }
      const rect = form.getBoundingClientRect();
      const heroRect = hero.getBoundingClientRect();
      const rightInset = Math.min(120, Math.max(34, window.innerWidth * 0.075));
      const layoutLeft = rect.left - shift;
      shift = heroRect.right - rightInset - rect.width - layoutLeft;
      form.style.translate = `${shift}px 0px`;
    };
    alignForm();
    const resizeObserver = new ResizeObserver(alignForm);
    resizeObserver.observe(hero);
    resizeObserver.observe(form);
    const themeObserver = new MutationObserver(alignForm);
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    window.addEventListener('resize', alignForm);
    return () => {
      resizeObserver.disconnect();
      themeObserver.disconnect();
      window.removeEventListener('resize', alignForm);
      form.style.translate = '';
    };
  }, []);
  const labels = lang === 'en'
    ? { kicker: 'FIND YOUR NEXT CAR', title: 'A car that fits your life.', make: 'Make', allMakes: 'Any make', body: 'Body style', allBodies: 'Any body style', model: 'Model or keyword', modelHint: 'Try Camry, GLC, Civic…', price: 'Budget up to', anyPrice: 'Any budget', find: 'Find vehicles' }
    : lang === 'kg'
      ? { kicker: 'УНААҢЫЗДЫ ТАНДАҢЫЗ', title: 'Сизге ылайык унаа.', make: 'Марка', allMakes: 'Бардык маркалар', allBodies: 'Бардык кузовдор', body: 'Кузов түрү', model: 'Модель же сөз', modelHint: 'Camry, GLC, Civic…', price: 'Баасы чейин', anyPrice: 'Каалаган баа', find: 'Унааларды табуу' }
      : { kicker: 'НАЙДИТЕ СВОЙ АВТОМОБИЛЬ', title: 'Машина для вашего следующего маршрута.', make: 'Марка', allMakes: 'Любая марка', body: 'Тип кузова', allBodies: 'Любой кузов', model: 'Модель или название', modelHint: 'Например, Camry или GLC', price: 'Бюджет до', anyPrice: 'Любая цена', find: 'Найти автомобиль' };

  return (
    <form ref={formRef} className="hero-search" onSubmit={(event) => { event.preventDefault(); scrollCatalog(); }}>
      <span className="hero-search-kicker"><i /> {labels.kicker}</span>
      <h2>{labels.title}</h2>
      <label>{labels.make}
        <select value={brand} onChange={(event) => setBrand(event.target.value)}>
          <option value="">{labels.allMakes}</option>
          {brands.map((item) => <option key={item.name} value={item.name}>{item.name}</option>)}
        </select>
      </label>
      <label>{labels.body}
        <select value={body} onChange={(event) => setBody(event.target.value)}>
          <option value="">{labels.allBodies}</option>
          <option value="Седан">Седан</option><option value="Кроссовер">Кроссовер</option>
          <option value="Внедорожник">Внедорожник</option><option value="Купе">Купе</option>
          <option value="Хэтчбек">Хэтчбек</option>
        </select>
      </label>
      <label>{labels.model}<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={labels.modelHint} /></label>
      <label>{labels.price}
        <select value={maxPrice} onChange={(event) => setMaxPrice(event.target.value)}>
          <option value="">{labels.anyPrice}</option><option value="35000">$35 000</option>
          <option value="60000">$60 000</option><option value="100000">$100 000</option><option value="250000">$250 000</option>
        </select>
      </label>
      <button className="hero-search-submit" type="submit">{labels.find}<span>↗</span></button>
      <p className="hero-search-foot">{lang==='en'?'Explore The Family Auto collection':lang==='kg'?'The Family Auto каталогунан унаа тандоо':'Подбор машин из каталога The Family Auto'}</p>
    </form>
  );
}

