  const visible=useMemo(()=>cars.filter(car=>((car.category||'passenger')===category)&&(!brand||car.brand===brand)&&(!body||car.type===body)&&car.name.toLowerCase().includes(search.toLowerCase())&&(!maxPrice||car.price<=Number(maxPrice))&&(!yearFrom||car.year>=Number(yearFrom))&&(!yearTo||car.year<=Number(yearTo))&&(!fuel||(fuel==='__unset'?!car.fuel:car.fuel===fuel))&&(!transmission||(transmission==='__unset'?!car.transmission:car.transmission===transmission))).sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:sort==='year'?b.year-a.year:sort==='name'?a.name.localeCompare(b.name):b.rating-a.rating),[cars,category,brand,body,search,maxPrice,yearFrom,yearTo,fuel,transmission,sort]);
