  const navigate=path=>{history.pushState({},'',path);setRoute(location.pathname + location.search);setMenu(false);setModal('');setRequestError('');window.scrollTo(0,0);if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView())};
  const loginOAuth=async provider=>{const enabled=provider==='google'?import.meta.env.VITE_GOOGLE_OAUTH_ENABLED:import.meta.env.VITE_GITHUB_OAUTH_ENABLED;if(enabled==='true'){location.href=`/api/oauth/${provider}`;return}if(import.meta.env.PROD){announce('Вход через этот сервис ещё не настроен');return}try{const result=await api('/api/auth/oauth',{method:'POST',body:JSON.stringify({provider})});localStorage.setItem('tfa-token',result.token);setUser(result.user);setModal('');announce(`${provider} demo login`)}catch(error){announce(error.message)}};
  const uploadCloudinary=async file=>{const cloud=import.meta.env.VITE_CLOUDINARY_CLOUD_NAME;const preset=import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET;if(!cloud||!preset)throw new Error('Сначала укажите Cloudinary cloud name и unsigned upload preset в .env');const data=new FormData();data.append('file',file);data.append('upload_preset',preset);const response=await fetch(`https://api.cloudinary.com/v1_1/${cloud}/image/upload`,{method:'POST',body:data});const result=await response.json();if(!response.ok)throw new Error(result.error?.message||'Не удалось загрузить изображение');return result.secure_url};
